head.script:
scwin.onpageload = function() {

};

scwin.btn_excel_onclick = function(e) {
    console.log("excel Down Click");
    var opt = {
        fileName :"excel.xlsx", 
        mergeCell : "true",
        colMergeTextAlign : "top"
    }

    grd_excel.advancedExcelDownload(opt);
};

scwin.checkVal = function() {
    var scrollX = WebSquare.wUnit.getDomById('mf_grd_excel_dataLayer').scrollLeft;
    return scrollX !== 0;
};

scwin.unitTest = function () {
    //Unit 
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('mf_grd_excel_dataLayer').scrollLeft += 100");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('mf_grd_excel_cell_0_5').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
};

scwin.unitTest();
